<?php
require __DIR__.'/../paginas/catalog_support.php';
function wikiCheck($ok,$message){if(!$ok)throw new RuntimeException($message);}
wikiCheck(function_exists('complementarLivroWikipedia'),'Falta alternativa Wikipedia para metadados ausentes');
$summary=['pageid'=>42,'title'=>'Dom Casmurro','type'=>'standard','description'=>'romance de Machado de Assis','extract'=>'Dom Casmurro é um romance escrito por Machado de Assis, publicado em 1899.','content_urls'=>['desktop'=>['page'=>'https://pt.wikipedia.org/wiki/Dom_Casmurro']],'thumbnail'=>['source'=>'https://upload.wikimedia.org/wikipedia/commons/1/11/Portrait.jpg']];
$calls=[];
$transport=function($url)use(&$calls,&$summary){$calls[]=$url;return str_contains($url,'/w/api.php')?['query'=>['search'=>[['pageid'=>42,'title'=>'Dom Casmurro']]]]:$summary;};
$book=['id'=>'google123','volumeInfo'=>['title'=>'Dom Casmurro','authors'=>['Machado de Assis'],'language'=>'pt'],'accessInfo'=>['accessViewStatus'=>'NONE']];
$filled=complementarLivroWikipedia($book,[],$transport);
wikiCheck($filled['volumeInfo']['description']===$summary['extract'],'Preencher sinopse ausente com o artigo do livro');
wikiCheck($filled['id']==='google123'&&$filled['volumeInfo']['authors']===['Machado de Assis']&&$filled['accessInfo']===$book['accessInfo'],'Preservar identidade, autoria e direitos');
wikiCheck(empty($filled['volumeInfo']['imageLinks']),'Não usar retrato ou imagem genérica como capa');
wikiCheck($filled['wikipedia']['url']==='https://pt.wikipedia.org/wiki/Dom_Casmurro','Atribuir a fonte utilizada');
$book['volumeInfo']['description']='Sinopse original';$book['volumeInfo']['imageLinks']=['thumbnail'=>'https://example.org/capa.jpg'];
$calls=[];$preserved=complementarLivroWikipedia($book,[],$transport);
wikiCheck($preserved===$book&&count($calls)===0,'Metadados completos não devem gerar consulta extra ou sobrescrita');
$summary['thumbnail']['source']='https://upload.wikimedia.org/wikipedia/commons/1/11/Capa_Dom_Casmurro.jpg';
$fallback=complementarLivroWikipedia(null,['title'=>'Dom Casmurro','authors'=>['Machado de Assis'],'language'=>'pt'],$transport);
wikiCheck($fallback['provider']==='wikipedia'&&$fallback['id']==='WIKI42','Falha total deve usar volume da Wikipedia com identidade própria');
wikiCheck($fallback['volumeInfo']['imageLinks']['thumbnail']===$summary['thumbnail']['source'],'Aceitar imagem identificada como capa');
wikiCheck(normalizarAcessoDigitalLivro($fallback)['link_leitura']===null,'Artigo enciclopédico não é livro completo');
$summary['type']='disambiguation';
wikiCheck(complementarLivroWikipedia(null,['title'=>'Dom Casmurro'],$transport)===null,'Não aceitar desambiguação');
$summary['type']='standard';$summary['description']='filme brasileiro baseado em um romance';
wikiCheck(complementarLivroWikipedia(null,['title'=>'Dom Casmurro'],$transport)===null,'Não confundir adaptação cinematográfica com livro');
$summary['description']='romance de Outro Autor';$summary['extract']='Dom Casmurro é um romance de Outro Autor.';
wikiCheck(complementarLivroWikipedia(null,['title'=>'Dom Casmurro','authors'=>['Machado de Assis']],$transport)===null,'Rejeitar autoria incompatível');
wikiCheck(complementarLivroWikipedia(null,[],$transport)===null,'Não buscar identificador opaco sem título conhecido');
wikiCheck(complementarLivroWikipedia(null,['title'=>'Dom Casmurro'],fn($url)=>null)===null,'Falha Wikipedia deve preservar ausência de informação');
$summary['description']='romance de Machado de Assis';$summary['extract']='Dom Casmurro é um romance escrito por Machado de Assis.';
$calls=[];$results=buscarVolumesExternos(['q'=>'Dom Casmurro','startIndex'=>0],'',function($url)use($transport){return str_contains($url,'googleapis.com')?null:$transport($url);});
wikiCheck($results['items'][0]['id']==='WIKI42','Pesquisa deve recorrer à Wikipedia quando Google falhar');
wikiCheck(!str_contains(implode(' ',$calls),'googleapis.com'),'Consulta Wikipedia não recebe chave Google');
$empty=buscarVolumesExternos(['q'=>'Livro inexistente','startIndex'=>0],'',fn($url)=>str_contains($url,'googleapis.com')?['items'=>[],'totalItems'=>0]:null);
wikiCheck(is_array($empty)&&$empty['items']===[]&&$empty['totalItems']===0,'Busca Google vazia e válida não deve virar erro quando as alternativas falham');
echo "PASS: alternativa Wikipedia, metadados ausentes, atribuição, identidade, direitos, homônimos e falhas\n";
